1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .game-over { font-size: 18px; font-weight: 700; color: #ff6b6b; }
27	  .p-I { background: #00c8e0 !important; }
28	  .p-O { background: #f0d000 !important; }
29	  .p-T { background: #a040f0 !important; }
30	  .p-S { background: #30c050 !important; }
31	  .p-Z { background: #e03030 !important; }
32	  .p-J { background: #3060f0 !important; }
33	  .p-L { background: #f08c20 !important; }
34	</style>
35	</head>
36	<body>
37	<div class="game">
38	  <div class="board" data-testid="board" id="board"></div>
39	  <div class="side">
40	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
41	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
42	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
43	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
44	    <div class="stat"><div class="label">Hold</div><div id="hold" data-testid="hold-piece" data-piece=""></div></div>
45	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
46	    <div class="help">← → move<br>↑ or X rotate<br>↓ soft drop<br>Space hard drop<br>C or Shift hold</div>
47	  </div>
48	</div>
49	<script>
50	(function () {
51	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
52	
53	  // [REQ-001] spawn shapes as [row, col] on the board
54	  var SHAPES = {
55	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
56	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
57	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
58	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
59	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
60	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
61	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
62	  };
63	
64	  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
65	  var BOX = {
66	    I: { size: 4, origin: [-1, 3] },
67	    O: { size: 2, origin: [0, 4] },
68	    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
69	    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
70	  };
71	  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
72	  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
73	  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
74	  // [REQ-003] points per clear by rows at once, times level; clearing together always beats one at a time
75	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
76	  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
77	  var QUEUE_SIZE = 3;             // [REQ-004] upcoming pieces kept in the queue
78	  var PREVIEW_COUNT = 1;          // [REQ-006] upcoming pieces shown in the preview
79	  var LINES_PER_LEVEL = 10;       // [REQ-007] lines cleared for each level gained
80	
81	  var state = {
82	    board: [],      // board[row][col] = letter or null
83	    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }
84	    upcoming: [],
85	    hold: null, holdUsed: false,  // [REQ-007] held letter; true once this piece has used its hold
86	    score: 0, level: 1, lines: 0,
87	    status: "running"
88	  };
89	  var timer = null;
90	
91	  var boardEl = document.getElementById("board");
92	  var cellEls = [];
93	  for (var r = 0; r < ROWS; r++) {
94	    cellEls.push([]);
95	    for (var c = 0; c < COLS; c++) {
96	      var el = document.createElement("div");
97	      el.className = "cell";
98	      el.setAttribute("data-testid", "cell");
99	      el.setAttribute("data-row", r);
100	      el.setAttribute("data-col", c);
101	      boardEl.appendChild(el);
102	      cellEls[r].push(el);
103	    }
104	  }
105	
106	  function emptyBoard() {
107	    var b = [];
108	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
109	    return b;
110	  }
111	
112	  function randomLetter() {
113	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
114	  }
115	
116	  function validLetters(queue) {
117	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
118	  }
119	
120	  // [REQ-004] keep enough upcoming pieces to fill the preview, padding with random ones
121	  function fillUpcoming() {
122	    while (state.upcoming.length < QUEUE_SIZE) state.upcoming.push(randomLetter());
123	  }
124	
125	  // [REQ-001] take the next piece from the queue, falling back to random
126	  function takeNext() {
127	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
128	    fillUpcoming();
129	    return letter;
130	  }
131	
132	  // [REQ-004] [REQ-007] a new piece that does not fit where it spawns ends the game; type defaults to the next in queue
133	  function spawn(type) {
134	    type = type || takeNext();
135	    var cells = SHAPES[type].map(function (p) { return [p[0], p[1]]; });
136	    if (!fits(cells)) {
137	      state.current = null;
138	      state.status = "gameover";
139	      if (timer) { clearInterval(timer); timer = null; }
140	      return;
141	    }
142	    state.current = {
143	      type: type,
144	      cells: cells,
145	      origin: BOX[type].origin.slice(),
146	      lockTicks: 0, lockResets: 0
147	    };
148	  }
149	
150	  function fits(cells) {
151	    return cells.every(function (p) {
152	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
153	    });
154	  }
155	
156	  function canMove(dr, dc) {
157	    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
158	  }
159	
160	  function tryMove(dr, dc) {
161	    if (!state.current || !canMove(dr, dc)) return false;
162	    var cur = state.current;
163	    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
164	    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
165	    if (dr > 0) cur.lockTicks = 0;
166	    return true;
167	  }
168	
169	  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
170	  function tryRotateCW() {
171	    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
172	    var turned = cur.cells.map(function (p) {
173	      var lr = p[0] - o[0], lc = p[1] - o[1];
174	      return [o[0] + lc, o[1] + n - 1 - lr];
175	    });
176	    // a rotation near the top edge is pushed down just enough to stay on the board
177	    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
178	    for (var i = 0; i < KICKS.length; i++) {
179	      var dc = KICKS[i];
180	      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
181	      if (fits(cand)) {
182	        cur.cells = cand;
183	        cur.origin = [o[0] + dr, o[1] + dc];
184	        return true;
185	      }
186	    }
187	    return false;
188	  }
189	
190	  // [REQ-002] [REQ-005] restart the lock delay, at most MAX_LOCK_RESETS times per piece
191	  function restartLockDelay() {
192	    var cur = state.current;
193	    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
194	  }
195	
196	  // [REQ-002] sideways move; while resting it restarts the lock delay
197	  function shift(dc) {
198	    var resting = !canMove(1, 0);
199	    if (tryMove(0, dc) && resting) restartLockDelay();
200	  }
201	
202	  // [REQ-003] [REQ-005] soft drop scores per cell; on a resting piece it restarts the lock delay like a sideways move
203	  function softDrop() {
204	    if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
205	    else restartLockDelay();
206	  }
207	
208	  // [REQ-003] remove full rows, drop everything above, count lines and score the clear
209	  function clearLines() {
210	    var kept = state.board.filter(function (row) { return !row.every(Boolean); });
211	    var cleared = ROWS - kept.length;
212	    if (!cleared) return;
213	    while (kept.length < ROWS) kept.unshift(new Array(COLS).fill(null));
214	    state.board = kept;
215	    state.score += CLEAR_POINTS[cleared] * state.level;
216	    // [REQ-007] one level per 10 lines crossed, counted on from the current level
217	    var gained = Math.floor((state.lines + cleared) / LINES_PER_LEVEL) - Math.floor(state.lines / LINES_PER_LEVEL);
218	    state.lines += cleared;
219	    if (gained > 0) { state.level += gained; startTimer(); }
220	  }
221	
222	  // [REQ-007] milliseconds between gravity steps at the current level
223	  function dropInterval() {
224	    return Math.max(100, 1000 - (state.level - 1) * 100);
225	  }
226	
227	  // [REQ-007] put the falling piece aside, or swap it with the held one; once per piece
228	  function holdPiece() {
229	    if (state.holdUsed) return;
230	    var held = state.hold;
231	    state.hold = state.current.type;
232	    state.holdUsed = true;
233	    spawn(held);
234	  }
235	
236	  // [REQ-001] [REQ-003] lock the falling piece, clear full rows and spawn the next one
237	  function lock() {
238	    var cur = state.current;
239	    cur.cells.forEach(function (p) {
240	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
241	    });
242	    clearLines();
243	    state.holdUsed = false;
244	    spawn();
245	  }
246	
247	  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
248	  function gravityStep() {
249	    if (state.status !== "running") return;
250	    if (!state.current) spawn();
251	    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
252	    render();
253	  }
254	
255	  // [REQ-001] [REQ-002] [REQ-003] player actions; hard drop locks at once, with no delay; drops score per cell
256	  function input(action) {
257	    if (state.status !== "running" || !state.current) return;
258	    if (action === "left") shift(-1);
259	    else if (action === "right") shift(1);
260	    else if (action === "rotateCW") tryRotateCW();
261	    else if (action === "softDrop") softDrop();
262	    else if (action === "hold") holdPiece();
263	    else if (action === "hardDrop") {
264	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
265	      lock();
266	    }
267	    render();
268	  }
269	
270	  // [REQ-001] synchronous render from the real game state
271	  function render() {
272	    var drawn = state.board.map(function (row) { return row.slice(); });
273	    if (state.current) {
274	      state.current.cells.forEach(function (p) {
275	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
276	      });
277	    }
278	    for (var r = 0; r < ROWS; r++) {
279	      for (var c = 0; c < COLS; c++) {
280	        var el = cellEls[r][c], letter = drawn[r][c];
281	        el.className = letter ? "cell p-" + letter : "cell";
282	        el.setAttribute("data-filled", letter ? "true" : "false");
283	        el.setAttribute("data-piece", letter || "");
284	      }
285	    }
286	    document.getElementById("score").textContent = String(state.score);
287	    document.getElementById("level").textContent = String(state.level);
288	    document.getElementById("lines").textContent = String(state.lines);
289	    renderNext();
290	    renderHold();
291	    document.getElementById("game-over").hidden = state.status !== "gameover";
292	  }
293	
294	  // [REQ-004] [REQ-006] only the next piece, coloured as on the board
295	  function renderNext() {
296	    var box = document.getElementById("next");
297	    box.innerHTML = "";
298	    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
299	      var grid = miniGrid(type);
300	      grid.setAttribute("data-testid", "next-piece-item");
301	      box.appendChild(grid);
302	    });
303	  }
304	
305	  // [REQ-007] the held piece, coloured as on the board
306	  function renderHold() {
307	    var box = document.getElementById("hold");
308	    box.innerHTML = "";
309	    box.setAttribute("data-piece", state.hold || "");
310	    if (state.hold) box.appendChild(miniGrid(state.hold));
311	  }
312	
313	  function miniGrid(type) {
314	    var grid = document.createElement("div");
315	    grid.className = "preview";
316	    grid.setAttribute("data-piece", type);
317	    var filled = {};
318	    SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
319	    for (var r = 0; r < 2; r++) {
320	      for (var c = 0; c < 4; c++) {
321	        var m = document.createElement("div");
322	        m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
323	        grid.appendChild(m);
324	      }
325	    }
326	    return grid;
327	  }
328	
329	  // [REQ-007] gravity timer at the level's speed; stays stopped once the game is over
330	  function startTimer() {
331	    if (timer) clearInterval(timer);
332	    timer = state.status === "running" ? setInterval(gravityStep, dropInterval()) : null;
333	  }
334	
335	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
336	  function newGame(queue) {
337	    state.board = emptyBoard();
338	    state.score = 0; state.level = 1; state.lines = 0;
339	    state.hold = null; state.holdUsed = false;
340	    state.status = "running";
341	    state.upcoming = validLetters(queue);
342	    state.current = null;
343	    spawn();
344	    startTimer();
345	    render();
346	  }
347	
348	  // [REQ-001] test control surface
349	  window.__tetris = {
350	    newGame: newGame,
351	    setQueue: function (queue) {
352	      state.upcoming = validLetters(queue);
353	      fillUpcoming();
354	      render();
355	    },
356	    setBoard: function (rows) {
357	      var b = emptyBoard();
358	      for (var r = 0; r < ROWS; r++) {
359	        var line = (rows && rows[r]) || "";
360	        for (var c = 0; c < COLS; c++) {
361	          var ch = line.charAt(c);
362	          b[r][c] = SHAPES[ch] ? ch : null;
363	        }
364	      }
365	      state.board = b;
366	      render();
367	    },
368	    // [REQ-007] set the level for testing; gravity speed follows
369	    setLevel: function (n) {
370	      state.level = Math.max(1, Math.floor(n) || 1);
371	      startTimer();
372	      render();
373	    },
374	    tick: function (n) {
375	      if (n === undefined) n = 1;
376	      for (var i = 0; i < n; i++) gravityStep();
377	    },
378	    input: input,
379	    getBoard: function () {
380	      return state.board.map(function (row) {
381	        return row.map(function (v) { return v || "."; }).join("");
382	      });
383	    },
384	    getState: function () {
385	      return {
386	        current: state.current
387	          ? {
388	              type: state.current.type,
389	              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
390	              lockTicks: state.current.lockTicks,
391	              lockResets: state.current.lockResets
392	            }
393	          : null,
394	        next: state.upcoming.slice(),
395	        hold: state.hold,
396	        dropInterval: dropInterval(),
397	        score: state.score, level: state.level, lines: state.lines,
398	        status: state.status
399	      };
400	    }
401	  };
402	
403	  document.addEventListener("keydown", function (e) {
404	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop", c: "hold", C: "hold", Shift: "hold" };
405	    var action = map[e.key];
406	    if (!action) return;
407	    e.preventDefault();
408	    input(action);
409	  });
410	
411	  newGame();
412	})();
413	</script>
414	</body>
415	</html>
