      stopTimer();
      state.status = "paused";
    } else if (state.status === "paused") {
      state.status = "running";
      stopTimer();
      timer = setTimeout(function () { gravityStep(); startTimer(); }, Math.max(0, dropInterval() - pausedElapsed));
    }
  }

  // [REQ-001] [REQ-002] [REQ-003] [REQ-009] player actions; hard drop locks at once, with no delay; drops score per cell
